<?php
namespace App\Models;use App\Casts\DateOnly;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides purchase request behavior within the WorkIntel application. */ class PurchaseRequest extends Model{protected $fillable=['uuid','workspace_id','requester_member_id','project_id','cost_center_id','request_number','title','vendor','currency','amount','status','needed_by','justification','reviewed_by','reviewed_at','purchase_order_number','created_by'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['amount'=>'decimal:2','needed_by'=>DateOnly::class,'reviewed_at'=>'datetime'];}/** Handles the requester operation for the current WorkIntel workflow. */ public function requester():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'requester_member_id');}/** Handles the project operation for the current WorkIntel workflow. */ public function project():BelongsTo{return $this->belongsTo(Project::class);}}
